effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

        float greyScale(in vec3 col) {
            return dot(col, vec3(0.2126, 0.7152, 0.0722));
        }

   /////////////////////////

   float noise(vec2 p)
    {
    	float s;
    	if(typeX == 0) { s = texture2DCv(black.texture,vec2(1.,2.*cos(1.0))*0.1*8. + p*1.).x; }
    	else if (typeX ==1) { s = texture2DCv(noisex.texture,vec2(1.,2.*cos(1.0))*0.1*8. + p*1.).x; }
    	s *= s;
    	return s;
    }

    float onOff(float a, float b, float c)
    {
    	float PROGO = autop? progressx + (acTime*0.5) : progressx;
    	return step(c, sin(PROGO + a*cos(PROGO*b)));
    }

    float ramp(float y, float start, float end)
    {
    	float inside = step(start,y) - step(end,y);
    	float fact = (y-start)/(end-start)*inside;
    	return (1.-fact) * inside;

    }

    float stripes(vec2 uv)
    {
    	float EVO = autod? progressd + (acTime*1.25) : progressd;
    	float noi = noise(uv*vec2(0.5,1.) + vec2(1.,3.));
    	return ramp(mod(uv.y*4. + EVO/2.+sin(EVO + sin(EVO*0.63)),1.),0.5,0.6)*noi;
    }

    vec3 getVideo(vec2 uv)
    {
    	vec2 look = uv;
    	float PROG = autop? progressx + (acTime*0.5) : progressx;
    	float window = 1./(1.+20.*(look.y-mod(PROG/4.,1.))*(look.y-mod(PROG/4.,1.)));
    	look.x = look.x + sin(look.y*10. + PROG)/50.*onOff(4.,4.,.3)*(1.+cos(PROG*80.))*window;
    	float vShift = 0.4*onOff(2.,3.,.9)*(sin(PROG)*sin(PROG*20.) +  (0.5 + 0.1*sin(PROG*200.)*cos(PROG)));
    	look.y = mod(look.y + vShift, 1.);
    	vec3 video = vec3(texture2DCv(inputImg.texture,look));
        if (greyscale) video = vec3(greyScale(video));
    	return video;
    }

    vec2 screenDistort(vec2 uv)
    {
    	uv -= vec2(.5,.5);
    	uv = uv*1.2*(1./1.2+2.*uv.x*uv.x*uv.y*uv.y);
    	uv += vec2(.5,.5);
    	return uv;
    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

        /////////////////////////


    	vec4 result;

    	vec2 uv = acScreenNorm.st;
    	uv = screenDistort(uv);
    	vec3 video = getVideo(uv);
    	float BLINK = autod? progressb + (acTime*0.5) : progressb;
    	float SLINES = autod? progressc + (acTime*0.5) : progressc;
    	float vigAmt = 3.+.3*sin(1.0 + 5.*cos(BLINK*5.));
    	float vignette = (1.-vigAmt*(uv.y-.5)*(uv.y-.5))*(1.-vigAmt*(uv.x-.5)*(uv.x-.5));

    	video += stripes(uv);
    	video += noise(uv*2.)/2.;
    	video *= vignette;
    	video *= (12.+mod(uv.y*30.+SLINES,1.))/13.;

    	result = vec4(video,alpha);

    	vec4 factor = result;
        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            factor *= texColor.a;
            resultfinal = factor + (texColor*(1.0-factor.a));
        } else if( blendMode==1 ) {         // multiply
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	// gl_FragColor = resultfinal;
    	gl_FragColor = mix(texColor,resultfinal,1.0) * texColor.a;
    }
